const searchInput = document.getElementById('search-input');
const searchPrediction = document.querySelector('.search-prediction');
const searchError = document.querySelector('.search-error');

searchInput.addEventListener('input', (e) => {
  const query = e.target.value.trim();

  if (query !== '') {
    // Call Google Search API or your preferred search engine
    fetch(`https://www.googleapis.com/customsearch/v1?key=YOUR_API_KEY&cx=YOUR_SEARCH_ENGINE_ID&q=${query}`)
      .then((response) => response.json())
      .then((data) => {
        const results = data.items;

        if (results.length > 0) {
          // Render live predictive search results
          const predictions = results.map((result) => `
            <li>
              <a href="${result.link}" target="_blank">
                ${result.title}
              </a>
            </li>
          `).join('');

          searchPrediction.innerHTML = predictions;
          searchPrediction.hidden = false;
        } else {
          // Show error message if no results found
          searchError.textContent = 'No results found.';
          searchError.hidden = false;
        }
      })
      .catch((error) => {
        console.error('Error:', error);
      });
  } else {
    searchPrediction.hidden = true;
  }
});

searchInput.addEventListener('focus', () => {
  searchInput.style.width = '100%';
});

searchInput.addEventListener('blur', () => {
  searchInput.style.width = '50%';
});

